import {computePdqf} from "./pdqf";
import {computeDct} from "./hash-dct";
import vpdq from "./vpdq";

let rescale: number,
	passes: number,
	block: number,
	doTmk: boolean,
	doVpdq: boolean,
	vpdqInterval: number;

self.onmessage = ({data}: MessageEvent) => {

	// initialise
	if (data.type === "init") {
		({rescale, passes, block, doTmk, doVpdq, vpdqInterval} = data);

	// process frame
	} else {
		const {videoFrame, frameIndex} = data as {videoFrame: VideoFrame; frameIndex: number},
			computeQuality = doVpdq && vpdq.includeFrame(vpdqInterval, frameIndex),
			{rawDct, quality} = computePdqf(videoFrame, rescale, passes, block, computeQuality),
			pdqHash = doVpdq ? computeDct(rawDct) : null,
			transfers: Transferable[] = [];

		if (pdqHash) {
			transfers.push(pdqHash.buffer);
		}
		if (doTmk) {
			transfers.push(rawDct.buffer);
		}

		(self as unknown as Worker).postMessage(
			{
				vpdq: pdqHash ? {hash: pdqHash.buffer, quality} : null,
				rawDct: doTmk ? rawDct.buffer : null,
			},
			transfers
		);
	}
};
